#!/usr/bin/env python3
"""Write the one tree of files every filesystem fixture holds.

    tree.py DIR [--sparse]

The same bytes are generated by `pat` in `tests/suites/fs_tree.rs`, which is
what the filesystem suites compare a walk against. --sparse adds a file with
data at its start, in its middle and at its end, and holes between.
"""
import os
import sys

TEXT = b"abcdefghij0123456789"

# (path, size). The seed of a file's bytes is its position in this list.
FILES = [
    ("empty", 0),
    ("tiny.txt", 10),
    ("sixty.bin", 60),
    ("sixtyone.bin", 61),
    ("p1.bin", 1025),
    ("big4k.bin", 4096),
    ("a/b/c/deep.bin", 5000),
    ("café 日本.txt", 300),
    ("long name with spaces and a long extension.markdown", 700),
    ("frag.bin", 100000),
]
MANY = 300
SPARSE_AT = (0, 30 << 20, 70 << 20)
SPARSE_LEN = (3000, 7000, 4)


def pat(seed, n):
    out = bytearray(n)
    for i in range(n):
        if (i // 64) % 2 == 0:
            out[i] = ((((i * 2654435761) + seed * 40503) & 0xFFFFFFFF) >> 13) & 0xFF
        else:
            out[i] = TEXT[(i + seed) % 20]
    return bytes(out)


def write(root, path, data):
    p = os.path.join(root, path)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "wb") as f:
        f.write(data)


def main():
    root = sys.argv[1]
    for seed, (path, size) in enumerate(FILES):
        write(root, path, pat(seed, size))
    for i in range(MANY):
        write(root, "many/file_%03d.dat" % i, pat(1000 + i, i % 97))
    os.makedirs(os.path.join(root, "emptydir"), exist_ok=True)
    if "--sparse" in sys.argv:
        with open(os.path.join(root, "sparse.bin"), "wb") as f:
            for k, (at, n) in enumerate(zip(SPARSE_AT, SPARSE_LEN)):
                f.seek(at)
                f.write(pat(2000 + k, n))


if __name__ == "__main__":
    main()
